package br.com.mathinclui.auth.token;

import br.com.mathinclui.auth.api.AuthProblemException; import br.com.mathinclui.auth.api.AuthResponse; import br.com.mathinclui.auth.api.SessionUser; import br.com.mathinclui.auth.security.*; import org.springframework.http.HttpStatus; import org.springframework.security.oauth2.jwt.JwtException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Clock; import java.time.Duration;
@Service public class RefreshTokenService { private final JwtTokenService jwtTokenService; private final RefreshTokenRepository repository; private final AuthPrincipalResolver principalResolver; private final Clock clock; public RefreshTokenService(JwtTokenService jwtTokenService,RefreshTokenRepository repository,AuthPrincipalResolver principalResolver,Clock clock){this.jwtTokenService=jwtTokenService;this.repository=repository;this.principalResolver=principalResolver;this.clock=clock;} @Transactional public AuthResponse issuePair(AuthPrincipal principal){var access=jwtTokenService.issueAccess(principal);var refresh=jwtTokenService.issueRefresh(principal);repository.save(new RefreshTokenSession(refresh.jti(),principal.subjectType(),principal.id(),refresh.expiresAt(),clock.instant()));var expiresIn=Math.max(1,Duration.between(clock.instant(),access.expiresAt()).toSeconds());return new AuthResponse(access.value(),refresh.value(),"Bearer",expiresIn,SessionUser.from(principal));} @Transactional public AuthResponse refresh(String refreshToken){try{var claims=jwtTokenService.parseRefresh(refreshToken);var session=repository.findByJti(claims.jti()).orElseThrow(this::invalidRefresh);if(session.getSubjectType()!=claims.subjectType()||!session.getSubjectId().equals(claims.subjectId())||!session.isActiveAt(clock.instant()))throw invalidRefresh();session.revoke(clock.instant());var principal=principalResolver.resolve(claims.subjectType(),claims.subjectId());return issuePair(principal);}catch(JwtException|IllegalArgumentException exception){throw invalidRefresh();}} @Transactional public void logout(String refreshToken){try{var claims=jwtTokenService.parseRefresh(refreshToken);repository.findByJti(claims.jti()).ifPresent(session->session.revoke(clock.instant()));}catch(JwtException|IllegalArgumentException ignored){}} @Transactional public void revokeAll(SubjectType type,Long subjectId){repository.revokeAllActive(type,subjectId,clock.instant());} private AuthProblemException invalidRefresh(){return new AuthProblemException(HttpStatus.UNAUTHORIZED,"Refresh token inválido ou expirado.");}}
